import type { SomewhereRuntimeContext } from '@somewhere-cloud/sdk/server';

/** Find an existing app user by email (pages the directory; no search-by-email API exists). */
export async function findUserByEmail(sw: SomewhereRuntimeContext, email: string) {
  const want = email.trim().toLowerCase();
  let cursor: string | undefined;
  for (let i = 0; i < 50; i++) {
    const page = await sw.auth.server.listUsers({ limit: 200, cursor });
    const hit = page.users.find((u: { email?: string | null }) => (u.email ?? '').toLowerCase() === want);
    if (hit) return hit as { id: string; email: string };
    if (!page.next_cursor) return null;
    cursor = page.next_cursor;
  }
  return null;
}

import type { SomewhereRuntimeContext } from '@somewhere-cloud/sdk/server';

/** Find an existing app user by exact email (sw.auth.server.listUsers({ emails }), see docs sw.auth). */
export async function findUserByEmail(sw: SomewhereRuntimeContext, email: string) {
  const { users } = await sw.auth.server.listUsers({ emails: [email.trim()] });
  const hit = users[0] as { id: string; email: string } | undefined;
  return hit ?? null;
}

functions.api/admin/users.ts:
export default async function (req, sw) {
  // Admin export: every user, with their role. Paging the whole directory is the point here.
  const all = [];
  let cursor;
  do {
    const page = await sw.auth.server.listUsers({ limit: 200, cursor });
    for (const u of page.users) all.push({ id: u.id, email: u.email, role: u.role });
    cursor = page.next_cursor;
  } while (cursor);
  const admins = all.filter((u) => u.role === 'admin');
  const search = new URL(req.url).searchParams.get('q') ?? '';
  const matches = all.filter((u) => (u.email ?? '').includes(search));
  const byId = all.find((u) => u.id === req.headers.get('x-user-id'));
  return Response.json({ total: all.length, admins: admins.length, matches, byId });
}

